        return [0, 0]

    def norm_pos(p):
        try:
            x, y = p
            return int(x), int(y)
        except Exception:
            return None

    sp = norm_pos(observation.get("self_position"))
    op = norm_pos(observation.get("opponent_position"))
    if sp is None:
        return [0, 0]
    sx, sy = sp

    obstacles = set()
    obs = observation.get("obstacles") or []
    for o in obs:
        q = norm_pos(o)
        if q is not None:
            obstacles.add(q)

    moves = [(-1, -1), (-1, 0), (-1, 1), (0, -1), (0, 0), (0, 1), (1, -1), (1, 0), (1, 1)]

    def inb(x, y):
        return 0 <= x < w and 0 <= y < h

    def ok(x, y):
        return inb(x, y) and (x, y) not in obstacles

    resources = observation.get("resources") or []
    respos = []
    for r in resources:
        q = norm_pos(r)
        if q is not None:
            respos.append(q)
    if not respos:
