        best_score = None
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not ok(nx, ny):
                continue
            dist = abs(nx - ox) + abs(ny - oy)
            score = -dist  # maximize distance from opponent => minimize -dist
            if best_score is None or score < best_score:
                best_score = score
                best = (dx, dy)
        return [best[0], best[1]] if best is not None else [0, 0]

