        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not ok(nx, ny):
                continue
            man = dist((nx, ny), (ox, oy))
            # small preference to move (avoid standing unless tied)
            score = (-man, 0 if (dx == 0 and dy == 0) else -0.01, (nx, ny))
            if best_score is None or score > best_score:
                best_score = score
                best_move = (dx, dy)
    else:
