        best_score = None
        for dx, dy in moves:
            nx, ny = sx + dx, sy + dy
            if not ok(nx, ny):
                continue
            opp_dx, opp_dy = greedy_pursuer((ox, oy), (nx, ny))
            nox, noy = ox + opp_dx, oy + opp_dy
            if not ok(nox, noy):
